"""Saves a JSON text in the project under a name with SetProjectData, reads it back, then deletes it."""
import json
import aclib

name = 'tapir-example/settings'

aclib.PrintJson (aclib.RunTapirCommand ('SetProjectData', {
    'values': [
        {'name': name, 'content': json.dumps ({'scale': 100, 'layer': 'Tapir'})}
    ]
}))
aclib.RunTapirCommand ('GetProjectData', {'names': [name]})

aclib.RunTapirCommand ('DeleteProjectData', {'names': [name]})

"""GetModulData returns the module data Tapir stored in the project (StoreModulData): every one without names, or
the given names. With includeContent false only the names and data versions are read. A name without module
data gets an error item.
"""
import aclib

aclib.RunTapirCommand ('StoreModulData', {
    'modulData': [
        {'name': 'tapir-example/get', 'content': '{"answer": 42}'}
    ]
})

aclib.PrintJson (aclib.RunTapirCommand ('GetModulData', {
    'includeContent': False
}))

aclib.PrintJson (aclib.RunTapirCommand ('GetModulData', {
    'names': ['tapir-example/get', 'tapir-example/missing']
}))

aclib.RunTapirCommand ('DeleteModulData', {
    'names': ['tapir-example/get']
})

"""Module data are the custom data sections of Archicad's ModulData Manager: text saved in the project file under
a name, kept apart from project data (SetProjectData). StoreModulData creates or overwrites them, with an
optional data version; storing is not an undoable step.
"""
import json
import aclib

settings = {'syncedAt': '2026-11-04T12:00:00Z', 'database': 'Épület DB'}

aclib.PrintJson (aclib.RunTapirCommand ('StoreModulData', {
    'modulData': [
        {'name': 'tapir-example/settings', 'content': json.dumps (settings, ensure_ascii = False), 'dataVersion': 2},
        {'name': 'tapir-example/notes', 'content': 'stored by the Tapir example'}
    ]
}))

values = aclib.RunTapirCommand ('GetModulData', {
    'names': ['tapir-example/settings', 'tapir-example/notes']
})['modulData']
assert json.loads (values[0]['content']) == settings
assert values[0]['dataVersion'] == 2

aclib.RunTapirCommand ('DeleteModulData', {
    'names': ['tapir-example/settings', 'tapir-example/notes']
})

"""DeleteModulData deletes the module data with the given names; a name without module data gets a failed
execution result. Deleting is not an undoable step.
"""
import aclib

aclib.RunTapirCommand ('StoreModulData', {
    'modulData': [
        {'name': 'tapir-example/delete', 'content': 'to be deleted'}
    ]
})

aclib.PrintJson (aclib.RunTapirCommand ('DeleteModulData', {
    'names': ['tapir-example/delete', 'tapir-example/missing']
}))

aclib.RunTapirCommand ('GetModulData', {
    'names': ['tapir-example/delete']
})
